	/// <summary>
	/// Warning: This class is generated by Claude in Oct 2026, and may be extraneous, excessive,
	/// overly complicated, logically incorrect and may contain logical fallacies.
	///
	/// A loopback FTPS server presents one certificate on the control connection and, optionally,
	/// a different one on data connections, as an attacker intercepting only the data path would.
	/// </summary>
	public class DataConnectionCertificateTests {
		private static readonly X509Certificate2 m_serverCertificate = CreateServerCertificate("CN=ftp.example.test");
		private static readonly X509Certificate2 m_foreignCertificate = CreateServerCertificate("CN=ftp.example.test");

		[Theory]
		[InlineData(false, "SslStream", false)]
		[InlineData(false, "SslStream", true)]
		[InlineData(true, "SslStream", false)]
		[InlineData(true, "SslStream", true)]
		[InlineData(false, "BouncyCastle", false)]
		[InlineData(false, "BouncyCastle", true)]
		[InlineData(true, "BouncyCastle", false)]
		[InlineData(true, "BouncyCastle", true)]
		public async Task ForeignDataCertificateIsRejected(bool asynchronous, string backend, bool upload) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_foreignCertificate, deadline.Token);
			var client = CreateClient(asynchronous, backend, server.Port);
			client.ValidateCertificate += (_, e) => e.Accept = IsServerCertificate(e.Certificate);

			var failure = await Record.ExceptionAsync(() => Transfer(client, upload, server.Payload, deadline.Token));
			await server.Completion.WaitAsync(deadline.Token);

			// SslStream validates the certificate after the handshake, so the server may see a completed
			// handshake; what matters is that the caller fails and no application data reaches the server.
			Assert.NotNull(failure);
			Assert.IsType<AuthenticationException>(failure);
			Assert.Empty(server.UploadedBytes);
		}

		[Theory]
		[InlineData(false, "SslStream", false)]
		[InlineData(false, "SslStream", true)]
		[InlineData(true, "SslStream", false)]
		[InlineData(true, "SslStream", true)]
		[InlineData(false, "BouncyCastle", false)]
		[InlineData(false, "BouncyCastle", true)]
		[InlineData(true, "BouncyCastle", false)]
		[InlineData(true, "BouncyCastle", true)]
		public async Task ControlCertificateIsAcceptedOnDataConnection(bool asynchronous, string backend, bool upload) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_serverCertificate, deadline.Token);
			var client = CreateClient(asynchronous, backend, server.Port);
			var validations = new List<bool>();
			client.ValidateCertificate += (_, e) => {
				validations.Add(e.IsDataConnection);
				e.Accept = IsServerCertificate(e.Certificate);
			};

			var downloaded = await Transfer(client, upload, server.Payload, deadline.Token);
			await server.Completion.WaitAsync(deadline.Token);

			Assert.True(server.DataHandshakeSucceeded);
			Assert.Equal(server.Payload, upload ? server.UploadedBytes : downloaded);
			// The handler validated the control connection only; the data connection reused that decision.
			Assert.Equal(new[] { false }, validations);
		}

		[Theory]
		[InlineData(false, false)]
		[InlineData(false, true)]
		[InlineData(true, false)]
		[InlineData(true, true)]
		public async Task HandlerCanAcceptForeignDataCertificate(bool asynchronous, bool upload) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_foreignCertificate, deadline.Token);
			var client = CreateClient(asynchronous, "SslStream", server.Port);
			var validations = new List<bool>();
			client.ValidateCertificate += (_, e) => {
				validations.Add(e.IsDataConnection);
				e.Accept = e.IsDataConnection
					? HashOf(e.Certificate) == m_foreignCertificate.GetCertHashString(HashAlgorithmName.SHA256)
					: IsServerCertificate(e.Certificate);
			};

			var downloaded = await Transfer(client, upload, server.Payload, deadline.Token);
			await server.Completion.WaitAsync(deadline.Token);

			Assert.True(server.DataHandshakeSucceeded);
			Assert.Equal(server.Payload, upload ? server.UploadedBytes : downloaded);
			Assert.Equal(new[] { false, true }, validations);
		}

