		[Theory]
		[InlineData(false, false)]
		[InlineData(false, true)]
		[InlineData(true, false)]
		[InlineData(true, true)]
		public async Task CloneValidatesItsControlCertificateLikeItsSource(bool asynchronous, bool foreign) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpsServer(foreign ? m_foreignCertificate : m_serverCertificate, m_serverCertificate, deadline.Token);
			using var source = CreateClient(asynchronous, "SslStream", server.Port);
			source.ValidateCertificate += (_, e) => e.Accept = IsServerCertificate(e.Certificate);

			using var clone = source.Clone();
			var failure = await Record.ExceptionAsync(() => ConnectAndDisconnect(clone, deadline.Token));
			await server.Completion.WaitAsync(deadline.Token);

			if (foreign) {
				Assert.IsType<AuthenticationException>(failure);
				Assert.DoesNotContain("PASS test-password", server.Commands);
			}
			else {
				Assert.Null(failure);
				Assert.Contains("PASS test-password", server.Commands);
			}
		}

		[Theory]
		[InlineData(false, false)]
		[InlineData(false, true)]
		[InlineData(true, false)]
		[InlineData(true, true)]
		public async Task AutoDetectAndAutoConnectDoNotFallBackToPlaintext(bool asynchronous, bool autoConnect) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			// The server offers explicit FTPS but also accepts an unencrypted login, as most servers do. A second
			// control connection is allowed so that a plaintext retry would be served and show up as PASS.
			using var server = new LoopbackFtpsServer(m_foreignCertificate, m_foreignCertificate, deadline.Token,
				controlConnections: 2, explicitTls: true);
			// No handler: the self-signed certificate fails the default validation.
			using var client = CreateClient(asynchronous, "SslStream", server.Port);

			var failure = await Record.ExceptionAsync(() => autoConnect
				? AutoConnect(client, deadline.Token)
				: AutoDetect(client, new FtpAutoDetectConfig(), deadline.Token));

			// Completion is not awaited: the second control connection never comes.
			Assert.IsType<AuthenticationException>(failure);
			Assert.Equal(new[] { "AUTH TLS" }, server.Commands);
		}

		[Theory]
		[InlineData(false)]
		[InlineData(true)]
		public async Task AutoDetectDoesNotFallBackToPlaintextWhenAProtocolIsListedTwice(bool asynchronous) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			// Both TLS attempts are rejected; a third control connection is allowed so that a plaintext retry
			// would be served and show up as PASS.
			using var server = new LoopbackFtpsServer(m_foreignCertificate, m_foreignCertificate, deadline.Token,
				controlConnections: 3, explicitTls: true);
			// No handler: the self-signed certificate fails the default validation.
			using var client = CreateClient(asynchronous, "SslStream", server.Port);
			// The last attempt is identified by its position, not by its value, which also occurs first.
			var config = new FtpAutoDetectConfig {
				ProtocolPriority = new List<SslProtocols> { SslProtocols.Tls12, SslProtocols.Tls12 },
			};

			var failure = await Record.ExceptionAsync(() => AutoDetect(client, config, deadline.Token));

			// Completion is not awaited: the third control connection never comes.
			Assert.IsType<AuthenticationException>(failure);
			Assert.Equal(new[] { "AUTH TLS", "AUTH TLS" }, server.Commands);
		}

		[Theory]
		[InlineData(false)]
		[InlineData(true)]
		public async Task AutoDetectTriesRemainingProtocolsAfterHandshakeFailure(bool asynchronous) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			// The server only speaks TLS 1.2, so the TLS 1.3 attempt fails its handshake and the TLS 1.2 one succeeds.
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_serverCertificate, deadline.Token,
				controlConnections: 2, explicitTls: true);
			using var client = CreateClient(asynchronous, "SslStream", server.Port);
			client.ValidateCertificate += (_, e) => e.Accept = IsServerCertificate(e.Certificate);
			var config = new FtpAutoDetectConfig {
				ProtocolPriority = new List<SslProtocols> { SslProtocols.Tls13, SslProtocols.Tls12 },
			};

			var profiles = await AutoDetect(client, config, deadline.Token);
			await server.Completion.WaitAsync(deadline.Token);

			var profile = Assert.Single(profiles);
			Assert.Equal(FtpEncryptionMode.Auto, profile.Encryption);
			Assert.Equal(SslProtocols.Tls12, profile.Protocols);
		}

		[Theory]
		[InlineData(false)]
		[InlineData(true)]
		public async Task AutoDetectKeepsCollectedProfilesWhenALaterHandshakeFails(bool asynchronous) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			// The server only speaks TLS 1.2 and also accepts an unencrypted login. TLS 1.2 succeeds first, then the
			// TLS 1.3 handshake fails as the last protocol, and the unencrypted profile is collected after that.
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_serverCertificate, deadline.Token,
				controlConnections: 3, explicitTls: true);
			using var client = CreateClient(asynchronous, "SslStream", server.Port);
			client.ValidateCertificate += (_, e) => e.Accept = IsServerCertificate(e.Certificate);
			var config = new FtpAutoDetectConfig {
				FirstOnly = false,
				IncludeImplicit = false,
				ProtocolPriority = new List<SslProtocols> { SslProtocols.Tls12, SslProtocols.Tls13 },
			};

			var profiles = await AutoDetect(client, config, deadline.Token);
			await server.Completion.WaitAsync(deadline.Token);

			// An encrypted profile had been found, so the failed handshake must not abort and discard it. The
			// unencrypted profile is listed as well because the caller allowed it and can see the encrypted option.
			Assert.Collection(profiles,
				profile => {
					Assert.Equal(FtpEncryptionMode.Auto, profile.Encryption);
					Assert.Equal(SslProtocols.Tls12, profile.Protocols);
				},
				profile => Assert.Equal(FtpEncryptionMode.None, profile.Encryption));
		}

		[Theory]
		[InlineData(false, "SslStream")]
		[InlineData(true, "SslStream")]
		[InlineData(false, "BouncyCastle")]
		[InlineData(true, "BouncyCastle")]
		public async Task ControlConnectionStaysUsableAfterRejectedDataCertificate(bool asynchronous, string backend) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpsServer(m_serverCertificate, m_foreignCertificate, deadline.Token);
			using var client = CreateClient(asynchronous, backend, server.Port);
			client.ValidateCertificate += (_, e) => e.Accept = IsServerCertificate(e.Certificate);

			// NOOP goes to the server unconditionally (GetWorkingDirectory would answer from its cache).
			FtpReply reply;
			if (client is AsyncFtpClient asyncClient) {
				await asyncClient.Connect(deadline.Token);
				await Assert.ThrowsAsync<AuthenticationException>(() => asyncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, server.Payload.Length, deadline.Token));
				reply = await asyncClient.Execute("NOOP", deadline.Token);
				await asyncClient.Disconnect(deadline.Token);
			}
			else {
				var syncClient = (FtpClient)client;
				syncClient.Connect();
				Assert.Throws<AuthenticationException>(() => syncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, server.Payload.Length));
				reply = syncClient.Execute("NOOP");
				syncClient.Disconnect();
			}
			await server.Completion.WaitAsync(deadline.Token);

			// The server's reply to the aborted transfer was consumed, so the next command received its own
			// reply on the same control connection instead of the stale one or a forced reconnect.
			Assert.Equal("200", reply.Code);
			Assert.Equal(1, client.Status.ConnectCount);
		}

		[Theory]
		[InlineData(false)]
		[InlineData(true)]
		public async Task PinnedCertificateFollowsTheCurrentControlConnection(bool asynchronous) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var first = new LoopbackFtpsServer(m_serverCertificate, m_serverCertificate, deadline.Token);
			using var second = new LoopbackFtpsServer(m_foreignCertificate, m_serverCertificate, deadline.Token);
			using var client = CreateClient(asynchronous, "SslStream", first.Port);
			var validations = new List<(bool IsDataConnection, string Certificate)>();
			client.ValidateCertificate += (_, e) => {
				validations.Add((e.IsDataConnection, HashOf(e.Certificate)));
				e.Accept = true;
			};

			var fromFirst = await ConnectDownloadDisconnect(client, first.Payload.Length, deadline.Token);
			client.Port = second.Port;
			var fromSecond = await ConnectDownloadDisconnect(client, second.Payload.Length, deadline.Token);
			await Task.WhenAll(first.Completion, second.Completion).WaitAsync(deadline.Token);

			Assert.Equal(first.Payload, fromFirst);
			Assert.Equal(second.Payload, fromSecond);
			// The second session pinned the foreign control certificate, so the server certificate is no longer
			// trusted implicitly on its data connection and the handler is asked about it.
			Assert.Equal(new[] {
				(false, HashOf(m_serverCertificate)),
				(false, HashOf(m_foreignCertificate)),
				(true, HashOf(m_serverCertificate)),
			}, validations);
		}

		private static bool IsServerCertificate(X509Certificate certificate) =>
			HashOf(certificate) == m_serverCertificate.GetCertHashString(HashAlgorithmName.SHA256);

		private static string HashOf(X509Certificate certificate) => certificate.GetCertHashString(HashAlgorithmName.SHA256);

		private static BaseFtpClient CreateClient(bool asynchronous, string backend, int port) {
			BaseFtpClient client = asynchronous
				? new AsyncFtpClient("127.0.0.1", "test-user", "test-password", port)
				: new FtpClient("127.0.0.1", "test-user", "test-password", port);
			client.Config.EncryptionMode = FtpEncryptionMode.Implicit;
			client.Config.DataConnectionType = FtpDataConnectionType.EPSV;
			client.Config.ConnectTimeout = client.Config.ReadTimeout = 5000;
			client.Config.DataConnectionConnectTimeout = client.Config.DataConnectionReadTimeout = 5000;
			if (backend == "BouncyCastle") {
				client.Config.CustomStream = typeof(BouncyCastleFtpStream);
				// Without resumption the certificate check is the only defense under test.
				client.Config.CustomStreamConfig = new BouncyCastleFtpConfig { RequireSessionResumption = false };
			}
			return client;
		}

		private static X509Certificate2 CreateServerCertificate(string subject) {
			using var key = RSA.Create(2048);
			var request = new CertificateRequest(subject, key, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
			using var generated = request.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddDays(1));
			// Schannel needs a PFX-imported key for server authentication on Windows.
#if NET9_0_OR_GREATER
			return X509CertificateLoader.LoadPkcs12(generated.Export(X509ContentType.Pfx), null);
#else
			return new X509Certificate2(generated.Export(X509ContentType.Pfx));
#endif
		}

		/// <summary>
		/// Connects, transfers the payload in the requested direction, and disconnects.
		/// Returns the downloaded bytes, or null for an upload.
		/// </summary>
		private static async Task<byte[]?> Transfer(BaseFtpClient client, bool upload, byte[] payload, CancellationToken token) {
			if (client is AsyncFtpClient asyncClient) {
				using (asyncClient) {
					await asyncClient.Connect(token);
					byte[]? downloaded = null;
					if (upload) {
						var stream = (FtpDataStream)await asyncClient.OpenWrite("/upload.bin", FtpDataType.Binary, -1, token);
						await stream.WriteAsync(payload, token);
						await stream.CloseAsync(token);
					}
					else {
						var stream = (FtpDataStream)await asyncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, payload.Length, token);
						using var received = new MemoryStream();
						await stream.CopyToAsync(received, token);
						await stream.CloseAsync(token);
						downloaded = received.ToArray();
					}
					await asyncClient.Disconnect(token);
					return downloaded;
				}
			}

			using var syncClient = (FtpClient)client;
			syncClient.Connect();
			byte[]? result = null;
			if (upload) {
				var stream = (FtpDataStream)syncClient.OpenWrite("/upload.bin", FtpDataType.Binary, -1);
				stream.Write(payload, 0, payload.Length);
				stream.Close();
			}
			else {
				var stream = (FtpDataStream)syncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, payload.Length);
				using var received = new MemoryStream();
				stream.CopyTo(received);
				stream.Close();
				result = received.ToArray();
			}
			syncClient.Disconnect();
			return result;
		}

		private static async Task ConnectAndDisconnect(BaseFtpClient client, CancellationToken token) {
			if (client is AsyncFtpClient asyncClient) {
				await asyncClient.Connect(token);
				await asyncClient.Disconnect(token);
				return;
			}

			var syncClient = (FtpClient)client;
			syncClient.Connect();
			syncClient.Disconnect();
		}

		private static Task<List<FtpProfile>> AutoDetect(BaseFtpClient client, FtpAutoDetectConfig config, CancellationToken token) =>
			client is AsyncFtpClient asyncClient
				? asyncClient.AutoDetect(config, token)
				: Task.Run(() => ((FtpClient)client).AutoDetect(config), token);

		private static Task<FtpProfile> AutoConnect(BaseFtpClient client, CancellationToken token) =>
			client is AsyncFtpClient asyncClient
				? asyncClient.AutoConnect(token)
				: Task.Run(() => ((FtpClient)client).AutoConnect(), token);

		/// <summary>
		/// Connects, downloads the payload and disconnects, leaving the client reusable.
		/// </summary>
		private static async Task<byte[]> ConnectDownloadDisconnect(BaseFtpClient client, int length, CancellationToken token) {
			using var received = new MemoryStream();
			if (client is AsyncFtpClient asyncClient) {
				await asyncClient.Connect(token);
				var stream = (FtpDataStream)await asyncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, length, token);
				await stream.CopyToAsync(received, token);
				await stream.CloseAsync(token);
				await asyncClient.Disconnect(token);
			}
			else {
				var syncClient = (FtpClient)client;
				syncClient.Connect();
				var stream = (FtpDataStream)syncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, length);
				stream.CopyTo(received);
				stream.Close();
				syncClient.Disconnect();
			}
			return received.ToArray();
		}

		/// <summary>
		/// Serves the requested number of FTPS control connections, one after the other: implicit FTPS by
		/// default, or explicit FTPS, where the session starts unencrypted and AUTH TLS upgrades it. Each RETR
		/// or STOR is carried over an EPSV data connection on which the server authenticates with the
		/// configured data certificate.
		/// </summary>
		private sealed class LoopbackFtpsServer : IDisposable {
			private readonly TcpListener m_listener = new TcpListener(IPAddress.Loopback, 0);
			private readonly X509Certificate2 m_controlCertificate;
			private readonly X509Certificate2 m_dataCertificate;
			private readonly bool m_explicitTls;
			private readonly MemoryStream m_uploaded = new MemoryStream();
			private readonly List<string> m_commands = new List<string>();
			private TcpListener? m_dataListener;
			private volatile bool m_stopped;

			internal LoopbackFtpsServer(X509Certificate2 controlCertificate, X509Certificate2 dataCertificate, CancellationToken token,
				int controlConnections = 1, bool explicitTls = false) {
				m_controlCertificate = controlCertificate;
				m_dataCertificate = dataCertificate;
				m_explicitTls = explicitTls;
				m_listener.Start();
				Completion = Task.Run(async () => {
					for (var served = 0; served < controlConnections; served++) {
						try {
							await Serve(token);
						}
						catch (Exception) when (m_stopped) {
							return; // Disposed while waiting for a connection that never came.
						}
					}
				});
			}

			internal byte[] Payload { get; } = RandomNumberGenerator.GetBytes(32769); // Cross TLS record boundaries.
			internal int Port => ((IPEndPoint)m_listener.LocalEndpoint).Port;
			internal Task Completion { get; }
			internal bool DataHandshakeSucceeded { get; private set; }
			internal byte[] UploadedBytes {
				get {
					lock (m_uploaded) {
						return m_uploaded.ToArray();
					}
				}
			}
			internal IReadOnlyList<string> Commands {
				get {
					lock (m_commands) {
						return m_commands.ToArray();
					}
				}
			}

			private static SslServerAuthenticationOptions Options(X509Certificate2 certificate) => new SslServerAuthenticationOptions {
				ServerCertificate = certificate,
				EnabledSslProtocols = SslProtocols.Tls12,
			};

			private async Task<SslStream?> AuthenticateControl(Stream stream, CancellationToken token) {
				var tls = new SslStream(stream, true);
				try {
					await tls.AuthenticateAsServerAsync(Options(m_controlCertificate), token);
					return tls;
				}
				catch (Exception error) when (error is AuthenticationException || error is IOException) {
					tls.Dispose();
					return null; // The client rejected the control certificate or offered no usable protocol.
				}
			}

			private async Task Serve(CancellationToken token) {
				using var peer = await m_listener.AcceptTcpClientAsync(token);
				SslStream? tls = null;
				if (!m_explicitTls && (tls = await AuthenticateControl(peer.GetStream(), token)) == null) {
					return;
				}

				// Readers and writers leave the stream open, so they can be replaced when AUTH TLS upgrades it.
				Stream control = (Stream?)tls ?? peer.GetStream();
				var reader = new StreamReader(control, Encoding.ASCII, false, 1024, true);
				var writer = new StreamWriter(control, Encoding.ASCII, 1024, true) { AutoFlush = true, NewLine = "\r\n" };
				try {
					await writer.WriteLineAsync("220 Loopback FTPS test");
					while (true) {
						var command = await reader.ReadLineAsync(token);
						if (command == null) {
							break;
						}
						lock (m_commands) {
							m_commands.Add(command);
						}
						var verb = command.Split(' ')[0];
						switch (verb) {
							// The plaintext reader may have buffered beyond this line. That is safe only because FluentFTP
							// never pipelines commands: nothing follows AUTH TLS until the 234 reply and the handshake.
							case "AUTH" when m_explicitTls && tls == null:
								await writer.WriteLineAsync("234 AUTH TLS successful");
								if ((tls = await AuthenticateControl(peer.GetStream(), token)) == null) {
									return;
								}
								reader = new StreamReader(tls, Encoding.ASCII, false, 1024, true);
								writer = new StreamWriter(tls, Encoding.ASCII, 1024, true) { AutoFlush = true, NewLine = "\r\n" };
								break;
							case "EPSV":
								m_dataListener = new TcpListener(IPAddress.Loopback, 0);
								m_dataListener.Start();
								await writer.WriteLineAsync($"229 Entering Extended Passive Mode (|||{((IPEndPoint)m_dataListener.LocalEndpoint).Port}|)");
								break;
							case "RETR":
							case "STOR":
								await writer.WriteLineAsync("150 Opening data connection");
								var transferred = await ServeData(verb == "STOR", token);
								await writer.WriteLineAsync(transferred ? "226 Transfer complete" : "426 Data connection TLS negotiation failed");
								break;
							case "QUIT":
								await writer.WriteLineAsync("221 Goodbye");
								return;
							default:
								await writer.WriteLineAsync(GetResponse(verb));
								break;
						}
					}
				}
				catch (IOException) {
					// The client may drop the control connection after a failed transfer.
				}
				finally {
					tls?.Dispose();
				}
			}

			private async Task<bool> ServeData(bool upload, CancellationToken token) {
				var listener = m_dataListener ?? throw new InvalidOperationException("RETR/STOR without EPSV.");
				m_dataListener = null;
				try {
					using var peer = await listener.AcceptTcpClientAsync(token);
					using var tls = new SslStream(peer.GetStream());
					try {
						await tls.AuthenticateAsServerAsync(Options(m_dataCertificate), token);
					}
					catch (Exception error) when (error is AuthenticationException || error is IOException) {
						return false; // The client rejected the data certificate.
					}
					DataHandshakeSucceeded = true;

					try {
						if (upload) {
							var buffer = new byte[8192];
							int read;
							while ((read = await tls.ReadAsync(buffer, token)) > 0) {
								lock (m_uploaded) {
									m_uploaded.Write(buffer, 0, read);
								}
							}
						}
						else {
							await tls.WriteAsync(Payload, token);
							await tls.ShutdownAsync();
						}
					}
					catch (IOException) {
						return false; // SslStream clients reject the certificate after the handshake and send an alert.
					}
					return true;
				}
				finally {
					listener.Stop();
				}
			}

			private static string GetResponse(string verb) => verb switch {
				"USER" => "331 Password required",
				"PASS" => "230 Logged in",
				"SYST" => "215 UNIX Type: L8",
				"PWD" => "257 \"/\"",
				"FEAT" => "500 No features",
				_ => "200 OK",
			};

			public void Dispose() {
				m_stopped = true;
				m_listener.Stop();
				m_dataListener?.Stop();
				m_uploaded.Dispose();
			}
		}
	}
}
